    if kind == 'quotes': return len(r) > 1 and r.startswith('"') and r.endswith('"')
    if kind == 'ps': return re.search(r'P\.S\.', r) is not None
    if kind == 'title': return re.search(r'<<[^\n<>]+>>', r) is not None
    if kind == 'minw': return len(words_of(r)) >= int(g(r'at least (\d+) words').group(1))
    if kind == 'maxw': return 0 < len(words_of(r)) < int(g(r'fewer than (\d+) words').group(1))
    if kind == 'paras':
        k = int(g(r'exactly (\d+) paragraphs').group(1)); return len([p for p in r.split('***') if p.strip()]) == k and r.count('***') == k - 1
