    hits = 0; tot = 0
    for st_ in range(len(seg) - win, max(len(seg) - 4000, win) - 1, -win):
        w_ = seg[st_:st_ + win]; tot += 1
        if seg.find(w_) < st_: hits += 1
    return hits / max(tot, 1)
